package com.fitpulse.model.entity;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="user_programs") public class UserProgram { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User user; @ManyToOne @JoinColumn(name="source_template_id") private ProgramTemplate sourceTemplate; @Column(nullable=false,length=150) private String name; private boolean active=true; @Column(nullable=false) private LocalDateTime createdAt; @OneToMany(mappedBy="userProgram",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("dayNumber, sortOrder") private List<UserProgramItem> items=new ArrayList<>(); @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public ProgramTemplate getSourceTemplate(){return sourceTemplate;} public void setSourceTemplate(ProgramTemplate v){sourceTemplate=v;} public String getName(){return name;} public String getDisplayName(){return name.replaceFirst("\\s+\\d+\\s+дни$", "");} public void setName(String v){name=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public List<UserProgramItem> getItems(){return items;} }
